const D = { beams: 6, scale: 1, hue: 320, energy: .6, spread: .6, speed: 1, density: .5, x: .5, y: .12, pattern: 'auto', style: 'volumetric', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;

const STY = {
  volumetric: { wire:false, dashed:false, truss:[210,10,32], node:[210,8,60], head:[220,12,22], sat:88, layers:3, air:1 },
  wireframe:  { wire:true,  dashed:false, truss:[190,60,55], node:[190,40,92], head:[190,55,45], sat:80, layers:1, air:0 },
  blueprint:  { wire:true,  dashed:true,  truss:[212,70,26], node:[196,55,80], head:[212,60,40], sat:70, layers:1, air:0 },
  neon:       { wire:false, dashed:false, truss:[280,30,14], node:[300,60,90], head:[280,40,26], sat:100, layers:2, air:0 },
  mono:       { wire:false, dashed:false, truss:[0,0,26],    node:[0,0,70],    head:[0,0,20],    sat:0,  layers:3, air:1 }
};
const st = STY[P.style] || STY.volumetric;

const nB = Math.max(2, Math.min(12, Math.round(P.beams)));
const trussY = P.y * height;
const trussX0 = width * 0.08, trussX1 = width * 0.92;
const cxRoom = P.x * width;

// ---- pattern selection (auto advances per section) ----
const PATS = ['fan','scan','crossfire','wave'];
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const arc = [.3,.5,.7,.9,.4,.7,1,.5][sec];
const pat = P.pattern === 'auto' ? PATS[sec % PATS.length] : P.pattern;

// ---- fixtures along truss (cache the static truss) ----
const key = width+'x'+height+'|'+nB+'|'+P.style+'|'+P.seed+'|'+Math.round(P.y*40)+'|'+Math.round(P.x*40);
if (!S.bg || S.key !== key) {
  if (!S.bg) S.bg = createGraphics(width, height); else S.bg.resizeCanvas(width, height);
  const g = S.bg; g.clear(); g.colorMode(g.HSB, 360, 100, 100, 100);
  const tr = st.truss, nd = st.node;
  const th = u * 0.028;
  // truss chords
  g.stroke(tr[0],tr[1],tr[2],90); g.strokeWeight(Math.max(2,u*0.004));
  g.line(trussX0, trussY - th/2, trussX1, trussY - th/2);
  g.line(trussX0, trussY + th/2, trussX1, trussY + th/2);
  // truss lattice diagonals
  g.strokeWeight(Math.max(1,u*0.002));
  const segs = Math.round((trussX1-trussX0)/(u*0.05));
  for (let i=0;i<segs;i++){ const a=trussX0+(i/segs)*(trussX1-trussX0), b=trussX0+((i+1)/segs)*(trussX1-trussX0);
    g.line(a, trussY-th/2, b, trussY+th/2); g.line(b, trussY-th/2, a, trussY+th/2); }
  // end rigging to ceiling
  g.stroke(tr[0],tr[1],tr[2]*0.7,70); g.strokeWeight(Math.max(1,u*0.0016));
  g.line(trussX0+u*0.05, trussY-th/2, trussX0+u*0.1, 0);
  g.line(trussX1-u*0.05, trussY-th/2, trussX1-u*0.1, 0);
  S.fx = [];
  for (let i=0;i<nB;i++){ const t = nB===1?0.5:i/(nB-1); const fx = trussX0 + t*(trussX1-trussX0); S.fx.push(fx); }
  S.key = key;
}
image(S.bg, 0, 0);

const fixes = S.fx || [];
const rootHue = P.hue;

// beam-angle programs — all driven by continuous K.t (never re-phases) + beat accents
const swScan = Math.sin(K.t * 0.55 * P.speed) ;             // -1..1 slow sweep
const swWave = K.t * 0.9 * P.speed;
const fanBase = (P.spread * 0.9 + 0.15) * (0.7 + 0.3*Math.sin(K.t*0.4*P.speed));
const kick = K.pulse*0.5 + A.bass*0.5;

function beamAngle(i) {
  const t = nB===1?0.5:i/(nB-1);
  const sgn = (t - 0.5);
  if (pat === 'fan')      return sgn * fanBase * 1.4 + 0.12*Math.sin(K.t*0.7 + i);
  if (pat === 'scan')     return swScan * (0.7 + P.spread*0.5) + sgn*0.05;
  if (pat === 'crossfire')return (i%2? 1 : -1) * (0.35 + P.spread*0.7) * (0.6 + 0.4*Math.sin(K.t*0.6*P.speed)) ;
  /* wave */              return Math.sin(swWave + t*TAU*1.2) * (0.5 + P.spread*0.8);
}

// ---- draw beams (additive volumetric cones) ----
push();
blendMode(ADD);
noStroke();
const L = height * (1.05 + P.scale*0.5);
const halfW = u * (0.012 + P.spread*0.02) * P.scale;
for (let i = 0; i < nB; i++) {
  const fx = fixes[i], fy = trussY + u*0.02;
  const ang = beamAngle(i);
  // per-beam color: split across hue, seeded jitter
  const bh = hw(rootHue + (i - nB/2) * 14 + (fr(i)-0.5)*30);
  // treble strobes brightness — PARTIAL (0.45..1), strobe-safe
  const strobe = 0.55 + 0.45*Math.pow(Math.max(0,Math.sin(K.t*(3+fr(i)*2)+i)),2);
  const bright = (0.5 + K.intensity*0.5) * (0.6 + 0.4*strobe) * (0.7 + P.energy*0.6) * (1 + kick*0.6);
  const dx = Math.sin(ang), dy = Math.cos(ang);
  // perpendicular
  const px = Math.cos(ang), py = -Math.sin(ang);
  const ex = fx + dx * L, ey = fy + dy * L;
  const baseW = halfW * (2.6 + P.spread*3);
  const layers = st.layers;
  if (st.wire) {
    // schematic ray
    stroke(bh, st.sat, st.node[2], 60 + bright*30); strokeWeight(Math.max(1, u*0.0016));
    if (st.dashed) { const nd=24; for (let d=0; d<nd; d+=2){ const a=d/nd, b=(d+1)/nd;
        line(fx+dx*L*a, fy+dy*L*a, fx+dx*L*b, fy+dy*L*b);} }
    else line(fx, fy, ex, ey);
    noStroke();
  } else {
    for (let k = layers; k >= 1; k--) {
      const t = k / layers;
      const wNear = halfW * (0.5 + 0.5*t);
      const wFar = baseW * t;
      const al = Math.min(30, (6 + bright*16) / t);
      fill(bh, st.sat, Math.min(100, 70 + bright*30), al);
      quad(fx - px*wNear, fy - py*wNear,
           fx + px*wNear, fy + py*wNear,
           ex + px*wFar,  ey + py*wFar,
           ex - px*wFar,  ey - py*wFar);
    }
    // hot core
    fill(bh, st.sat*0.4, 100, 30 + bright*40);
    quad(fx - px*halfW*0.4, fy - py*halfW*0.4,
         fx + px*halfW*0.4, fy + py*halfW*0.4,
         ex + px*baseW*0.3, ey + py*baseW*0.3,
         ex - px*baseW*0.3, ey - py*baseW*0.3);
  }
  // fixture glint at source
  fill(st.node[0], st.node[1], st.node[2], 60 + bright*30);
  ellipse(fx, fy, u*0.012, u*0.012);
}
blendMode(BLEND);
pop();

// ---- moving-head fixture bodies (rotate to beam) ----
push();
for (let i = 0; i < nB; i++) {
  const fx = fixes[i], ang = beamAngle(i);
  push(); translate(fx, trussY + u*0.008); rotate(ang);
  noStroke(); fill(st.head[0], st.head[1], st.head[2], 95);
  rectMode(CENTER); rect(0, u*0.012, u*0.02, u*0.024, u*0.004);
  // lens
  const bh = hw(rootHue + (i - nB/2) * 14);
  fill(bh, st.sat*0.6, 100, 90); ellipse(0, u*0.022, u*0.012, u*0.012);
  pop();
}
pop();

// ---- faint atmospheric haze band (volumetric only) ----
if (st.air) {
  push(); blendMode(ADD); noStroke();
  const hz = hw(rootHue);
  fill(hz, st.sat*0.3, 100, 3 + (K.intensity*4 + A.rms*6));
  const bandY = trussY + height*0.5;
  ellipse(cxRoom, bandY, width*1.1, height*0.7);
  blendMode(BLEND); pop();
}

// ---- drifting dust motes catching the beams (density) ----
if (P.density > 0.02) {
  push(); blendMode(ADD); noStroke();
  const nM = Math.round(P.density * 60);
  for (let i = 0; i < nM; i++) {
    const mx = (fr(i)*1.2 - 0.1 + Math.sin(K.t*0.05*P.speed + i)*0.04) * width;
    const my = ((fr(i+40) + K.t*(0.01 + fr(i+7)*0.02)*P.speed) % 1) * height;
    const tw = 0.3 + 0.7*Math.pow(Math.max(0,Math.sin(K.t*(1.5+fr(i)*3)+i)),4) + A.treble*0.6;
    const mh = hw(rootHue + (fr(i)-0.5)*40);
    fill(mh, st.sat*0.5, 100, 8 + tw*20);
    ellipse(mx, my, u*0.004*(0.6+tw), u*0.004*(0.6+tw));
  }
  blendMode(BLEND); pop();
}

blendMode(BLEND);
if (drawingContext) drawingContext.shadowBlur = 0;
